WITH recent_web_events AS (SELECT * FROM web_events WHERE event_type = 'add_to_cart'), summary AS (SELECT page, DATE_TRUNC('MONTH', event_time) AS event_month, MIN(event_time) AS first_event_time, AVG(duration_sec) AS avg_duration_sec FROM recent_web_events GROUP BY page, DATE_TRUNC('MONTH', event_time)) SELECT * FROM summary WHERE avg_duration_sec < 290 ORDER BY avg_duration_sec DESC, page, event_month LIMIT 10
